<?php
namespace App\Http\Controllers;use App\Models\ComplaintType;use Illuminate\Http\Request;
class ComplaintTypeController extends Controller{public function index(Request $r){$q=ComplaintType::latest()->when($r->search,fn($q,$v)=>$q->where('name','like',"%$v%"));return view('complaint-types.index',['types'=>$q->paginate(10)->withQueryString()]);}public function store(Request $r){ComplaintType::create($this->data($r));return back()->with('success','Complaint type created.');}public function update(Request $r,ComplaintType $complaintType){$complaintType->update($this->data($r,$complaintType->id));return back()->with('success','Complaint type updated.');}public function toggle(ComplaintType $complaintType){$complaintType->update(['status'=>!$complaintType->status]);return back()->with('success','Status updated.');}public function destroy(ComplaintType $complaintType){if($complaintType->complaints()->exists())return back()->with('error','This type is used by a complaint and cannot be deleted.');$complaintType->delete();return back()->with('success','Complaint type deleted.');}private function data(Request $r,$id=null){return $r->validate(['name'=>'required|string|max:100|unique:complaint_types,name,'.($id?:'NULL').',id','description'=>'nullable|string|max:500','status'=>'required|boolean']);}}
